-- Process interviews (docs/plan.md §1.217): a link an operator sends one client contact about one
-- process; the questions and answers, the sample files added, and once finished the current-state
-- map, the open questions, the reuse check and the build drafted from it. A new table only, so the
-- previous Worker keeps working. Generated by drizzle-kit; the grants and row-level security at
-- the end are hand-written.
CREATE TABLE "process_interview" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"contact_id" uuid NOT NULL,
	"process" text NOT NULL,
	"area" text,
	"status" text DEFAULT 'open' NOT NULL,
	"language" text DEFAULT 'en' NOT NULL,
	"expires_at" timestamp with time zone NOT NULL,
	"turns" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"question" text,
	"documents" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"outputs" jsonb,
	"reuse" jsonb,
	"build_id" uuid,
	"cost_usd" numeric(14, 4) DEFAULT '0' NOT NULL,
	"log" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"created_by" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"finished_at" timestamp with time zone,
	CONSTRAINT "process_interview_id_tenant_key" UNIQUE("id","tenant_id"),
	CONSTRAINT "process_interview_status_check" CHECK ("process_interview"."status" in ('open', 'finished', 'closed')),
	CONSTRAINT "process_interview_process_check" CHECK (char_length("process_interview"."process") between 1 and 200),
	CONSTRAINT "process_interview_finished_check" CHECK ("process_interview"."status" <> 'finished' or ("process_interview"."outputs" is not null and "process_interview"."finished_at" is not null))
);
